import { z } from 'zod';
import { validationError } from '../../errors/app-error.ts';

export const MAX_ITEMS = 100;
const MAX_NAME = 200;
const MAX_PRICE = 999_999_999;
const MAX_QUANTITY = 99_999;

const hasAtMostDecimals = (value: number, decimals: number) => {
  const factor = 10 ** decimals;
  return Math.abs(value * factor - Math.round(value * factor)) < 1e-6;
};

const itemSchema = z.object({
  /** The id of an item that already exists: lets the server keep its "generated by AI" mark when it is unchanged */
  id: z.uuid().optional(),
  name: z
    .string({ error: 'Введите название позиции' })
    .trim()
    .min(1, 'Введите название позиции')
    .max(MAX_NAME, `Название позиции не длиннее ${MAX_NAME} символов`),
  price: z
    .number({ error: 'Цена должна быть числом' })
    .min(0, 'Цена не может быть отрицательной')
    .max(MAX_PRICE, 'Слишком большая цена')
    .refine((value) => hasAtMostDecimals(value, 2), 'Цена: не более двух знаков после запятой'),
  quantity: z
    .number({ error: 'Количество должно быть числом' })
    .positive('Количество должно быть больше нуля')
    .max(MAX_QUANTITY, 'Слишком большое количество')
    .refine(
      (value) => hasAtMostDecimals(value, 3),
      'Количество: не более трёх знаков после запятой',
    )
    .default(1),
});

const itemsSchema = z.array(itemSchema).max(MAX_ITEMS, `Позиций не больше ${MAX_ITEMS}`);

export type ItemInput = z.infer<typeof itemSchema>;

/** The list of items from a request body (`{ items: [...] }`). */
export function parseItemsBody(body: unknown): ItemInput[] {
  const parsed = z.object({ items: itemsSchema }).safeParse(body);
  if (parsed.success) return parsed.data.items;
  throw validationError('INVALID_ITEMS', parsed.error.issues[0]!.message);
}

/** Items sent together with a new expense (the same checks). */
export const createItemsSchema = itemsSchema.optional();
